//! The grammars the benchmarks run against.
//!
//! All but JSON are ordinary crates. JSON is regenerated by `build.rs` and
//! reached through an `extern`, which lives here rather than in the bench itself
//! so the crate records the dependency on the archive: referenced only from a
//! bench target, the linker drops it and the symbol comes out undefined.
use tree_feller::LanguageFn;

extern "C" {
    /// Regenerated at ABI 15 by `build.rs`; see there for why it is not a crate.
    #[cfg(have_json)]
    fn tree_sitter_json() -> *const ();
}

/// `(name, grammar)` for everything that could be built.
pub fn grammars() -> Vec<(&'static str, LanguageFn)> {
    #[allow(unused_mut)]
    let mut out = vec![
        ("c", tree_sitter_c::LANGUAGE),
        ("go", tree_sitter_go::LANGUAGE),
        ("solidity", tree_sitter_solidity::LANGUAGE),
        ("datazinc", tree_sitter_datazinc::LANGUAGE),
        ("minizinc", tree_sitter_minizinc::LANGUAGE),
    ];
    #[cfg(have_json)]
    out.push(("json", unsafe { LanguageFn::from_raw(tree_sitter_json) }));
    out
}

pub fn find(name: &str) -> Option<LanguageFn> {
    grammars()
        .into_iter()
        .find(|(n, _)| *n == name)
        .map(|(_, g)| g)
}

/// Deterministic benchmark inputs.
///
/// Generated rather than checked in: a few megabytes of `.dzn` is not something
/// to put in a repository, and generating means the numbers do not move because
/// someone edited a fixture.
pub mod inputs {
    /// A data file: a handful of long arrays, which is what `.dzn` mostly is and
    /// where the visible layer's memory behaviour actually matters.
    pub fn dzn(bytes: usize) -> String {
        let mut out = String::with_capacity(bytes + 64);
        let mut n: u32 = 0;
        let mut array = 0;
        while out.len() < bytes {
            out.push_str(&format!("data{array} = ["));
            for i in 0..20_000 {
                if i > 0 {
                    out.push(',');
                }
                n = n.wrapping_mul(1_103_515_245).wrapping_add(12_345);
                out.push_str(&(n >> 16).to_string());
            }
            out.push_str("];\n");
            array += 1;
        }
        out
    }

    pub fn json(bytes: usize) -> String {
        let mut out = String::from("{\"records\":[");
        let mut n: u32 = 7;
        let mut first = true;
        while out.len() < bytes {
            if !first {
                out.push(',');
            }
            first = false;
            n = n.wrapping_mul(1_103_515_245).wrapping_add(12_345);
            out.push_str(&format!(
                "{{\"id\":{},\"name\":\"item-{}\",\"tags\":[\"a\",\"b\"],\"ok\":true,\"score\":{}.5}}",
                n >> 16,
                n % 1000,
                n % 97
            ));
        }
        out.push_str("]}");
        out
    }

    const C_UNIT: &str = r#"
    static int helper___N__(int a, int b) {
      int total = 0;
      for (int i = 0; i < a; i++) { total += (i % 2) ? b : -b; }
      switch (total) { case 0: return 1; default: break; }
      return total;
    }
    struct point___N__ { int x, y; const char *label; };
    "#;

    const GO_UNIT: &str = r#"
    type Shape__N__ struct {
    	Width, Height float64
    	Label         string
    }

    func (s Shape__N__) Area() float64 { return s.Width * s.Height }

    func run__N__(items []int) (int, error) {
    	total := 0
    	for i, v := range items {
    		if i%2 == 0 {
    			total += v
    		}
    	}
    	return total, nil
    }
    "#;

    const MZN_UNIT: &str = r#"
    int: n__N__ = 10;
    set of int: N__N__ = 1..n__N__;
    array[N__N__] of var 1..100: x__N__;
    constraint forall(i in N__N__ where i > 1)(x__N__[i] >= x__N__[i - 1]);
    constraint sum(i in N__N__)(x__N__[i]) <= 500;
    "#;

    const SOL_UNIT: &str = r#"
    contract Thing__N__ {
        mapping(address => uint256) private balances;
        event Sent(address indexed from, uint256 value);
        function send__N__(address to, uint256 value) public {
            require(value > 0);
            unchecked { balances[msg.sender] -= value; }
            balances[to] += value;
            emit Sent(msg.sender, value);
        }
    }
    "#;

    /// Distinct identifiers per repetition, so the grammar is not just re-parsing
    /// one symbol and the lexer's keyword path stays realistic. The marker is
    /// `__N__` rather than something shorter because `%` and `$` occur in the units.
    pub fn numbered(unit: &str, bytes: usize) -> String {
        let mut out = String::with_capacity(bytes + unit.len());
        let mut i = 0usize;
        while out.len() < bytes {
            out.push_str(&unit.replace("__N__", &i.to_string()));
            i += 1;
        }
        out
    }

    /// The input for one grammar, of roughly `bytes` -- data files get more,
    /// because the workload this library exists for is the one where the tree
    /// dwarfs the data.
    pub fn of(name: &str, bytes: usize) -> String {
        match name {
            "datazinc" => dzn(4 * bytes),
            "json" => json(2 * bytes),
            "minizinc" => numbered(MZN_UNIT, bytes),
            "c" => numbered(C_UNIT, bytes),
            "go" => numbered(GO_UNIT, bytes),
            "solidity" => numbered(SOL_UNIT, bytes),
            other => panic!("no benchmark input for {other}"),
        }
    }
}
